AUTO_MIRROR = {
    "arrow_back",
    "send",
    "reply",
    "forward",
    "format_list_bulleted",
    "help_outline",
    "logout",
    "keyboard_arrow_right",
}


def emit(name: str, paths: list[str]) -> None:
    am = ' android:autoMirrored="true"' if name in AUTO_MIRROR else ""
    body = "".join(
        f'    <path android:fillColor="@android:color/white" android:pathData="{p}"/>\n'
        for p in paths
    )
    xml = (
        '<?xml version="1.0" encoding="utf-8"?>\n'
        '<vector xmlns:android="http://schemas.android.com/apk/res/android"\n'
        '    android:width="24dp"\n'
        '    android:height="24dp"\n'
        '    android:viewportWidth="24"\n'
        f'    android:viewportHeight="24"{am}>\n'
        f"{body}</vector>\n"
    )
    (OUT_DIR / f"ic_{name}.xml").write_text(xml, encoding="utf-8")


def main() -> None:
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    for name, paths in PATHS.items():
        emit(name, paths)
    print("wrote", len(PATHS), "icons")


if __name__ == "__main__":
    main()
